    static Button Btn(string text, Action action) { var b=new Button{Text=text,AutoSize=true,Padding=new Padding(12,5,12,5),BackColor=Color.FromArgb(37,99,235),ForeColor=Color.White,FlatStyle=FlatStyle.Flat,Margin=new Padding(4)};b.FlatAppearance.BorderSize=0;b.Click+=(_,_)=>action();return b; }
    static void Layout(TabPage page,string title,string help,Control editor,Control actions,Control output){var grid=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=5,Padding=new Padding(10)};grid.RowStyles.Add(new(SizeType.Absolute,42));grid.RowStyles.Add(new(SizeType.Absolute,36));grid.RowStyles.Add(new(SizeType.Percent,45));grid.RowStyles.Add(new(SizeType.AutoSize));grid.RowStyles.Add(new(SizeType.Percent,55));var h=new Label{Text=title,Font=new Font("Segoe UI",17,FontStyle.Bold),ForeColor=Color.FromArgb(26,43,70),Dock=DockStyle.Fill};var l=new Label{Text=help,ForeColor=Color.DimGray,Dock=DockStyle.Fill};grid.Controls.Add(h,0,0);grid.Controls.Add(l,0,1);grid.Controls.Add(editor,0,2);grid.Controls.Add(actions,0,3);grid.Controls.Add(output,0,4);page.Controls.Add(grid);}
    TabPage StackPage(){
        var p=Page("Стек");var commands=Box("1,Кот\n1,Пёс\n3\n2\n5",true);var output=Box("Выберите действие или запустите сценарий ниже.",true);var visual=StackVisual();var stack=new LinkedStack<string>();var value=new TextBox{Width=180,Font=new Font("Segoe UI",11),PlaceholderText="Например: яблоко"};var status=new Label{Text="Стек пуст",AutoSize=true,ForeColor=Color.FromArgb(71,85,105),Padding=new Padding(10,9,0,0)};
        void Report(string text){output.Text=text+"\r\n\r\nСейчас в стеке: "+(stack.IsEmpty?"пусто":stack.ToString());status.Text=stack.IsEmpty?"Стек пуст":$"Элементов: {stack.Items.Count()}";DrawStack(visual,stack.Items,true);}
        var actions=new FlowLayoutPanel{AutoSize=true,Dock=DockStyle.Fill};actions.Controls.Add(new Label{Text="Значение",AutoSize=true,Padding=new Padding(4,9,0,0)});actions.Controls.Add(value);actions.Controls.Add(Btn("＋ Добавить наверх",()=>{if(string.IsNullOrWhiteSpace(value.Text)){output.Text="Введите значение, затем нажмите «Добавить наверх».";value.Focus();return;}stack.Push(value.Text.Trim());Report($"Добавлено наверх: {value.Text.Trim()}");value.Clear();value.Focus();}));actions.Controls.Add(Btn("↓ Снять верхний",()=>Report(stack.Pop(out var x)?$"Снято со стека: {x}":"Стек пуст — снимать нечего.")));actions.Controls.Add(Btn("Показать вершину",()=>Report(stack.Top(out var x)?$"Верхний элемент: {x}":"Стек пуст — вершины нет.")));actions.Controls.Add(Btn("Пуст ли стек?",()=>Report($"Стек {(stack.IsEmpty?"пуст":"не пуст")}.")));actions.Controls.Add(Btn("Очистить стек",()=>{stack=new LinkedStack<string>();Report("Стек очищен.");}));actions.Controls.Add(status);
        var scenarioPanel=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoSize=true};scenarioPanel.Controls.Add(new Label{Text="Учебный сценарий (команды через пробел): 1,текст — добавить; 2 — снять; 3 — вершина; 4 — пуст?; 5 — печать",AutoSize=true,Padding=new Padding(4,8,0,0)});var speed=new NumericUpDown{Minimum=100,Maximum=2000,Increment=100,Value=500,Width=70};scenarioPanel.Controls.Add(speed);scenarioPanel.Controls.Add(Btn("▶ Проиграть сценарий",async()=>{var parts=commands.Text.Split((char[]?)null,StringSplitOptions.RemoveEmptyEntries);var log=new StringBuilder();for(var i=0;i<parts.Length;i++){var token=parts[i];var pair=token.Split(',',2);string message;switch(pair[0]){case "1" when pair.Length>1:stack.Push(pair[1]);message=$"Добавить наверх: {pair[1]}";break;case "2":message=stack.Pop(out var popped)?$"Снять верхний: {popped}":"Стек пуст: снятие пропущено";break;case "3":message=stack.Top(out var top)?$"Вершина: {top}":"Стек пуст: вершины нет";break;case "4":message=stack.IsEmpty?"Стек пуст":"Стек не пуст";break;case "5":message=$"Содержимое: {stack}";break;default:message=$"Неизвестная команда: {token}";break;}log.AppendLine($"Шаг {i+1}/{parts.Length} · {message}");Report(log.ToString());await Task.Delay((int)speed.Value);}Report(log+"Сценарий завершён.");}));
        var editorArea=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=2};editorArea.RowStyles.Add(new(SizeType.Percent,60));editorArea.RowStyles.Add(new(SizeType.Percent,40));editorArea.Controls.Add(commands,0,0);editorArea.Controls.Add(scenarioPanel,0,1);var workArea=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2};workArea.ColumnStyles.Add(new(SizeType.Percent,53));workArea.ColumnStyles.Add(new(SizeType.Percent,47));workArea.Controls.Add(editorArea,0,0);workArea.Controls.Add(visual,1,0);
        Layout(p,"Стек · последний добавленный снимается первым","Используйте кнопки для отдельных действий. Сценарий ниже показывает выполнение нескольких команд по шагам.",workArea,actions,output);return p;
    }    static FlowLayoutPanel StackVisual(){var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,BackColor=Color.FromArgb(235,241,250),Padding=new Padding(14)};panel.Controls.Add(new Label{Text="ВЕРШИНА  ↓",AutoSize=true,Font=new Font("Segoe UI",10,FontStyle.Bold),ForeColor=Color.FromArgb(37,99,235),Margin=new Padding(8,0,0,8)});panel.Controls.Add(new Label{Name="StackItems",Text="Стек пуст\\r\\nДобавьте элемент командой 1,значение",AutoSize=true,ForeColor=Color.Gray,Margin=new Padding(18,4,0,4)});return panel;}
    static void DrawStack(FlowLayoutPanel panel,IEnumerable<string> values,bool highlight=false){panel.SuspendLayout();for(int i=panel.Controls.Count-1;i>=1;i--)panel.Controls.RemoveAt(i);var items=values.ToArray();if(items.Length==0)panel.Controls.Add(new Label{Text="Стек пуст\\r\\nДобавьте элемент командой 1,значение",AutoSize=true,ForeColor=Color.Gray,Margin=new Padding(18,4,0,4)});else for(int i=0;i<items.Length;i++){var card=new Label{Text=$"{(i==0?"TOP  ↓  ":"        ")}{items[i]}",Width=Math.Max(160,panel.ClientSize.Width-55),Height=36,TextAlign=ContentAlignment.MiddleLeft,Padding=new Padding(9,0,0,0),BackColor=i==0&&highlight?Color.FromArgb(251,191,36):i==0?Color.FromArgb(219,234,254):Color.White,ForeColor=Color.FromArgb(26,43,70),BorderStyle=BorderStyle.FixedSingle,Margin=new Padding(8,3,8,3),Font=new Font("Segoe UI",10,i==0?FontStyle.Bold:FontStyle.Regular)};panel.Controls.Add(card);}panel.ResumeLayout();panel.Invalidate();}
    async void RunStackAnimation(TextBox editor,TextBox outbox,FlowLayoutPanel visual,bool animate){
        var tokens=editor.Text.Split((char[]?)null,StringSplitOptions.RemoveEmptyEntries);var s=new LinkedStack<string>();var sb=new StringBuilder();var speed=editor.Tag as NumericUpDown;var buttons=editor.Parent?.Parent?.Controls.OfType<FlowLayoutPanel>().FirstOrDefault()?.Controls.OfType<Button>().ToArray()??Array.Empty<Button>();foreach(var b in buttons)b.Enabled=false;DrawStack(visual,s.Items);
        try{for(int i=0;i<tokens.Length;i++){var t=tokens[i];if(animate){var pos=0;for(int j=0;j<i;j++)pos+=tokens[j].Length+1;editor.Focus();editor.Select(pos,t.Length);outbox.Text=$"Команда {i+1} из {tokens.Length}: {t}\r\nДо выполнения: [{s}]\r\n\r\n{sb}";await Task.Delay((int)(speed?.Value??600));}var a=t.Split(',',2);string result;switch(a[0]){case "1":if(a.Length>1){s.Push(a[1]);result=$"Push({a[1]})";}else result="Ошибка: Push задается как 1,значение";break;case "2":result=s.Pop(out var v)?$"Pop() → {v}":"Pop(): стек пуст";break;case "3":result=s.Top(out var q)?$"Top() → {q}":"Top(): стек пуст";break;case "4":result=$"isEmpty() → {s.IsEmpty}";break;case "5":result=$"Print() → [{s}]";break;default:result=$"Неизвестная команда: {t}";break;}sb.AppendLine($"{i+1}. {t}: {result} | стек: [{s}]");DrawStack(visual,s.Items,animate);outbox.Text=sb+ $"\r\nТекущее состояние стека: [{s}]";if(animate)await Task.Delay((int)(speed?.Value??600));}editor.Select(0,0);outbox.Text=sb+$"\r\nГотово. Итоговый стек: [{s}]";}catch(Exception ex){outbox.AppendText("\r\nОшибка: "+ex.Message);}finally{foreach(var b in buttons)b.Enabled=true;}
    }    TabPage QueuePage(){
        var p=Page("Очередь");
        var items=new List<string>();
        var commands=Box("1,Анна\n1,Борис\n3\n2\n5",true);
        var output=Box("Здесь появится описание каждого шага.",true);
        var picture=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false,AutoScroll=true,BackColor=Color.FromArgb(235,241,250),Padding=new Padding(14),FlowDirection=FlowDirection.LeftToRight};
        var status=new Label{Text="Очередь пуста",AutoSize=true,Padding=new Padding(8),ForeColor=Color.FromArgb(71,85,105)};
        var value=new TextBox{Width=150,Font=new Font("Segoe UI",11),PlaceholderText="Введите значение"};
        var delay=new NumericUpDown{Minimum=150,Maximum=2000,Increment=100,Value=600,Width=75};
        var actions=new FlowLayoutPanel{AutoSize=true,Dock=DockStyle.Fill};
        void Draw(){picture.Controls.Clear();picture.Controls.Add(new Label{Text="НАЧАЛО →",AutoSize=true,Font=new Font("Segoe UI",10,FontStyle.Bold),ForeColor=Color.FromArgb(37,99,235),Margin=new Padding(4,15,10,0)});if(items.Count==0)picture.Controls.Add(new Label{Text="Очередь пуста",AutoSize=true,ForeColor=Color.Gray,Margin=new Padding(8,15,8,0)});for(int i=0;i<items.Count;i++)picture.Controls.Add(new Label{Text=items[i]+(i<items.Count-1?"  →":""),AutoSize=true,MinimumSize=new Size(88,48),TextAlign=ContentAlignment.MiddleCenter,BackColor=i==0?Color.FromArgb(191,219,254):Color.White,BorderStyle=BorderStyle.FixedSingle,Margin=new Padding(4,6,4,6),Font=new Font("Segoe UI",10,i==0?FontStyle.Bold:FontStyle.Regular)});picture.Controls.Add(new Label{Text="→ КОНЕЦ",AutoSize=true,Font=new Font("Segoe UI",10,FontStyle.Bold),ForeColor=Color.FromArgb(37,99,235),Margin=new Padding(10,15,4,0)});status.Text=items.Count==0?"Очередь пуста":$"Элементов: {items.Count} · первый: {items[0]}";}
        void Report(string message){Draw();output.Text=message+"\r\nТекущее состояние: "+(items.Count==0?"пусто":string.Join(" → ",items));}
        var single=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoSize=true};single.Controls.Add(new Label{Text="Значение",AutoSize=true,Padding=new Padding(4,9,0,0)});single.Controls.Add(value);single.Controls.Add(Btn("＋ Добавить в конец",()=>{if(string.IsNullOrWhiteSpace(value.Text)){Report("Введите значение в поле слева.");value.Focus();return;}items.Add(value.Text.Trim());Report($"Добавлено в конец: {value.Text.Trim()}");value.Clear();value.Focus();}));single.Controls.Add(Btn("Снять из начала",()=>{if(items.Count==0){Report("Очередь пуста — удалять нечего.");return;}var x=items[0];items.RemoveAt(0);Report($"Из начала снято: {x}");}));single.Controls.Add(Btn("Показать первый",()=>Report(items.Count==0?"Очередь пуста.":$"Первый в очереди: {items[0]}")));single.Controls.Add(Btn("Очистить очередь",()=>{items.Clear();Report("Очередь очищена.");}));single.Controls.Add(status);
        var guide=new Label{Text="КОМАНДЫ СЦЕНАРИЯ\r\n1,значение — добавить значение в конец (пример: 1,Ирина)\r\n2 — удалить первый элемент\r\n3 — показать первый элемент\r\n4 — проверить, пуста ли очередь\r\n5 — вывести все элементы от начала к концу\r\n\r\nРазделяйте команды пробелами или переводами строки. После кода 1 обязательно поставьте запятую и значение. Значения могут быть словами или числами.",Dock=DockStyle.Fill,AutoSize=false,BackColor=Color.White,ForeColor=Color.FromArgb(51,65,85),Padding=new Padding(10)};
        var speedrow=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoSize=true};speedrow.Controls.Add(new Label{Text="Пауза между командами (мс)",AutoSize=true,Padding=new Padding(4,8,0,0)});speedrow.Controls.Add(delay);speedrow.Controls.Add(Btn("▶ Выполнить по шагам",async()=>{var tokens=commands.Text.Split((char[]?)null,StringSplitOptions.RemoveEmptyEntries);if(tokens.Length==0){Report("Добавьте команды в поле сценария.");return;}items.Clear();Draw();var log=new StringBuilder();for(int i=0;i<tokens.Length;i++){var token=tokens[i];commands.Focus();commands.Select(0,0);var z=token.Split(',',2);string message;switch(z[0]){case "1" when z.Length==2:items.Add(z[1]);message=$"Добавить в конец: {z[1]}";break;case "1":message="Неверно: используйте 1,значение";break;case "2":if(items.Count==0)message="Очередь пуста — удаление пропущено";else{message=$"Снять из начала: {items[0]}";items.RemoveAt(0);}break;case "3":message=items.Count==0?"Очередь пуста":$"Первый элемент: {items[0]}";break;case "4":message=items.Count==0?"Очередь пуста":"Очередь не пуста";break;case "5":message=$"Печать: {string.Join(" → ",items)}";break;default:message=$"Неизвестная команда: {token}";break;}Draw();log.AppendLine("Шаг "+(i+1)+" из "+tokens.Length);log.AppendLine("Команда: "+token);log.AppendLine("Действие: "+message);log.AppendLine("Состояние: "+(items.Count==0?"пусто":string.Join(" → ",items)));log.AppendLine();output.Text=log.ToString();await Task.Delay((int)delay.Value);}output.AppendText("Сценарий завершён.");}));speedrow.Controls.Add(Btn("Сравнить время реализаций",()=>{var tokens=commands.Text.Split((char[]?)null,StringSplitOptions.RemoveEmptyEntries);output.Text=RunQueue(tokens,false)+"\r\n"+RunQueue(tokens,true);}));
        var scenario=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=2};scenario.RowStyles.Add(new(SizeType.Absolute,130));scenario.RowStyles.Add(new(SizeType.Percent,100));scenario.Controls.Add(guide,0,0);scenario.Controls.Add(commands,0,1);
        var body=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=2};body.RowStyles.Add(new(SizeType.Percent,38));body.RowStyles.Add(new(SizeType.Percent,62));body.Controls.Add(picture,0,0);body.Controls.Add(scenario,0,1);
        var actionArea=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=2,AutoSize=true};actionArea.RowStyles.Add(new(SizeType.AutoSize));actionArea.RowStyles.Add(new(SizeType.AutoSize));actionArea.Controls.Add(single,0,0);actionArea.Controls.Add(speedrow,0,1);Layout(p,"Очередь · первым обслуживается тот, кто пришёл первым","Добавляйте в конец и снимайте из начала. Ручные кнопки — для одной операции; сценарий — для пошагового разбора команд.",body,actionArea,output);Draw();return p;
    }    static string RunQueue(string[] ops,bool standard){var a=new LinkedQueue<string>();var b=new Queue<string>();var sb=new StringBuilder();var sw=Stopwatch.StartNew();foreach(var t in ops){var z=t.Split(',',2);switch(z[0]){case "1":if(z.Length>1){if(standard)b.Enqueue(z[1]);else a.Enqueue(z[1]);}break;case "2":if(standard){if(b.Count>0)b.Dequeue();}else a.Dequeue(out _);break;case "3":sb.AppendLine(standard?(b.Count>0?$"Front → {b.Peek()}":"Очередь пуста"):(a.Front(out var v)?$"Front → {v}":"Очередь пуста"));break;case "4":sb.AppendLine(standard?$"isEmpty → {b.Count==0}":$"isEmpty → {a.IsEmpty}");break;case "5":sb.AppendLine(standard?$"Print → [{string.Join(" ",b)}]":$"Print → [{a}]");break;}}sw.Stop();return $"{(standard?"Queue<T>":"Связный список")} — {sw.Elapsed.TotalMilliseconds:F3} мс\r\n{sb}";}
    TabPage ExpressionsPage(){var p=Page("Выражения");var inf=Box("2+2*(3+4)");var post=Box("7 8 + 3 2 + *");var result=Box("Результат и шаги вычисления появятся здесь.",true);var visual=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.LeftToRight,WrapContents=true,AutoScroll=true,BackColor=Color.FromArgb(235,241,250),Padding=new Padding(12)};var controls=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoSize=true};controls.Controls.Add(Btn("Преобразовать и вычислить",()=>{try{var pf=Program.ToPostfix(inf.Text);post.Text=pf;result.Text=$"Инфиксная формула: {inf.Text}\r\nПостфиксная запись: {pf}\r\nРезультат: {Program.Evaluate(pf)}\r\nСложность: O(n) времени и O(n) памяти.";}catch(Exception ex){result.Text="Ошибка: "+ex.Message;}}));controls.Controls.Add(Btn("▶ Показать вычисление по шагам",async()=>{try{visual.Controls.Clear();var stack=new Stack<double>();var log=new StringBuilder();var tokens=post.Text.Split((char[]?)null,StringSplitOptions.RemoveEmptyEntries);for(int i=0;i<tokens.Length;i++){var t=tokens[i];if(double.TryParse(t,NumberStyles.Float,CultureInfo.InvariantCulture,out var number))stack.Push(number);else{double Pop()=>stack.Count>0?stack.Pop():throw new FormatException("Недостаточно операндов");switch(t){case "+":{var b=Pop();stack.Push(Pop()+b);break;}case "-":{var b=Pop();stack.Push(Pop()-b);break;}case "*":{var b=Pop();stack.Push(Pop()*b);break;}case "/":case ":":{var b=Pop();stack.Push(Pop()/b);break;}case "^":{var b=Pop();stack.Push(Math.Pow(Pop(),b));break;}case "sin":stack.Push(Math.Sin(Pop()));break;case "cos":stack.Push(Math.Cos(Pop()));break;case "ln":stack.Push(Math.Log(Pop()));break;case "sqrt":stack.Push(Math.Sqrt(Pop()));break;default:throw new FormatException("Неизвестный токен: "+t);}}var card=new Label{Text=$"{t}\r\nСтек: {string.Join(" · ",stack.Reverse())}",AutoSize=true,MinimumSize=new Size(130,58),TextAlign=ContentAlignment.MiddleCenter,BackColor=Color.FromArgb(219,234,254),BorderStyle=BorderStyle.FixedSingle,Margin=new Padding(5)};visual.Controls.Add(card);log.AppendLine($"Шаг {i+1}: {t} → [{string.Join(", ",stack.Reverse())}]");result.Text=log.ToString();await Task.Delay(450);}if(stack.Count!=1)throw new FormatException("После вычисления должен остаться один результат.");result.AppendText($"\r\nРезультат: {stack.Pop()}\r\nСложность: O(n) времени, O(n) памяти.");}catch(Exception ex){result.AppendText("\r\nОшибка: "+ex.Message);}}));controls.Controls.Add(Btn("Загрузить postfix.txt",()=>{using var d=new OpenFileDialog{Filter="Текстовые файлы|*.txt|Все файлы|*.*"};if(d.ShowDialog()==DialogResult.OK)post.Text=File.ReadAllText(d.FileName);}));var inputs=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=2};inputs.ColumnStyles.Add(new(SizeType.Percent,50));inputs.ColumnStyles.Add(new(SizeType.Percent,50));inputs.RowStyles.Add(new(SizeType.Absolute,30));inputs.RowStyles.Add(new(SizeType.Percent,100));inputs.Controls.Add(new Label{Text="Обычная формула",Dock=DockStyle.Fill},0,0);inputs.Controls.Add(new Label{Text="Постфиксная запись",Dock=DockStyle.Fill},1,0);inputs.Controls.Add(inf,0,1);inputs.Controls.Add(post,1,1);var body=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=2};body.RowStyles.Add(new(SizeType.Percent,35));body.RowStyles.Add(new(SizeType.Percent,65));body.Controls.Add(inputs,0,0);body.Controls.Add(visual,0,1);Layout(p,"Вычисление выражений","Формула: + сложение, − вычитание, * умножение, / или : деление, ^ степень. Скобки задают порядок. Функции sin, cos, ln, sqrt пишутся перед аргументом в postfix. Десятичная точка — точка.",body,controls,result);return p;}    TabPage ListPage(){var p=Page("Список");var editor=Box("1 2 2 3 4 4 5",true);var input=Box("",false);var outbox=Box("",true);var panel=new FlowLayoutPanel{AutoSize=true,Dock=DockStyle.Fill};panel.Controls.Add(Btn("Показать операции",()=>{var l=Parse();var sb=new StringBuilder($"Исходный список: {l}\r\nРазличных элементов: {l.DistinctCount()}\r\n");var dedup=Parse();dedup.RemoveDuplicates();sb.AppendLine($"Удалить повторы: {dedup}");var rev=Parse();rev.Reverse();sb.AppendLine($"Развернуть: {rev}");var first=Parse();first.MoveFirstToEnd();sb.AppendLine($"Первый в конец: {first}");var last=Parse();last.MoveLastToFront();sb.AppendLine($"Последний в начало: {last}");var sorted=Parse();sorted.InsertSorted(int.TryParse(input.Text,out var n)?n:0);sb.AppendLine($"Вставить по порядку ({input.Text}): {sorted}");var removed=Parse();if(int.TryParse(input.Text,out n))removed.RemoveAll(n);sb.AppendLine($"Удалить все ({input.Text}): {removed}");var dup=Parse();dup.Duplicate();sb.AppendLine($"Удвоить список: {dup}");var split=Parse();var tail=split.SplitAfterFirst(int.TryParse(input.Text,out n)?n:0);sb.AppendLine($"Разбить после первого {input.Text}: [{split}] | [{tail}]");outbox.Text=sb.ToString();}));panel.Controls.Add(new Label{Text="Число для вставки/удаления/разбиения:",AutoSize=true,Padding=new Padding(5,10,0,0)});input.Width=90;panel.Controls.Add(input);panel.Controls.Add(Btn("Считать список из файла",()=>{using var d=new OpenFileDialog{Filter="Текстовые файлы|*.txt|Все файлы|*.*"};if(d.ShowDialog()==DialogResult.OK)editor.Text=File.ReadAllText(d.FileName);}));LinkedList<int> Parse(){var l=new LinkedList<int>();foreach(var t in editor.Text.Split((char[]?)null,StringSplitOptions.RemoveEmptyEntries))if(int.TryParse(t,out var n))l.AddLast(n);return l;}Layout(p,"Алгоритмы собственного списка","Введите целые числа через пробел; число справа используется в выбранной операции. Кнопка покажет реверс, перенос первого/последнего, удаление повторов, вставку по порядку, удаление заданного числа, удвоение и разбиение после первого вхождения.",editor,panel,outbox);return p;}
}


















